import re

_RUN = re.compile(r'(.)\1*')


def longest_run(s):
    """Длина самой длинной серии одинаковых подряд идущих символов; для пустой строки 0."""
    return max((m.end() - m.start() for m in _RUN.finditer(s)), default=0)

from itertools import groupby


def longest_run(s):
    """Длина самой длинной серии одинаковых подряд идущих символов; для пустой строки 0."""
    return max((sum(1 for _ in run) for _, run in groupby(s)), default=0)

def clamp_list(xs, lo, hi):
    """Каждый элемент ограничивается отрезком [lo, hi] (lo <= hi)."""
    smallest, largest = min(xs), max(xs)
    if lo <= smallest and largest <= hi:
        return list(xs)
    if largest <= lo:
        return [lo] * len(xs)
    if smallest >= hi:
        return [hi] * len(xs)
    return [lo if x < lo else hi if x > hi else x for x in xs]

